use core.files as files
use core.process as process
use core.term as term

fn has_key(keys: [String], key: String) Bool -> {
    loop k in keys {
        if k == key -> return true
    }
    return false
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    text :: files.read(path) ?? panic("read failed")

    section_names := [String]{}
    section_keys := [[String]]{}
    section_values := [[String]]{}
    section_inherits := [String]{}

    current := -1

    loop line in text.lines() {
        trimmed :: ~line.trim()
        if trimmed.is_empty() -> next

        if trimmed.starts_with("[") {
            name :: ~trimmed.after("[").before("]")
            section_names.push(~name)
            section_keys.push([String]{})
            section_values.push([String]{})
            section_inherits.push("")
            current = section_names.len() - 1
        } else {
            if current < 0 {
                term.eprint("error: key-value pair outside of section")
                panic("bad format")
            }
            eq_parts :: trimmed.split("=").to_list()
            if eq_parts.len() < 2 -> next
            key :: ~eq_parts[0].trim()
            raw_value :: ~eq_parts[1].trim()
            value :: ~raw_value.after("\"").before("\"")

            if key == "inherits" {
                section_inherits[current] = ~value
            } else {
                if has_key(section_keys[current], key) {
                    term.eprint("error: duplicate key '{key}' in section '{section_names[current]}'")
                    panic("duplicate key")
                }
                section_keys[current].push(~key)
                section_values[current].push(~value)
            }
        }
    }

    loop s in 0..<section_names.len() {
        parent :: ~section_inherits[s]
        if !parent.is_empty() {
            pi := -1
            loop j in 0..<section_names.len() {
                if section_names[j] == parent {
                    pi = j
                    break
                }
            }
            if pi >= 0 {
                parent_keys :: section_keys[pi]
                parent_values :: section_values[pi]
                loop pk_i in 0..<parent_keys.len() {
                    pk :: parent_keys[pk_i]
                    if !has_key(section_keys[s], pk) {
                        new_keys := [String]{}
                        new_values := [String]{}
                        new_keys.push(~pk)
                        new_values.push(~parent_values[pk_i])
                        old_keys :: section_keys[s]
                        old_values :: section_values[s]
                        loop ok_i in 0..<old_keys.len() {
                            new_keys.push(~old_keys[ok_i])
                            new_values.push(~old_values[ok_i])
                        }
                        section_keys[s] = new_keys
                        section_values[s] = new_values
                    }
                }
            }
        }

        keys :: section_keys[s]
        vals :: section_values[s]
        loop k_i in 0..<keys.len() {
            print("{section_names[s]}.{keys[k_i]}={vals[k_i]}")
        }
    }
}

