use core.term as term

enum Command {
    List
    Inspect
    Remove
}

struct Options {
    command: Command
    name: String
    format: String
    dry_run: Bool
}

fn run() {
    args :: process.argv()
    if args.len() < 2 {
        term.eprint("error: missing command")
        panic("missing command")
    }

    cmd_str :: args[1]
    command := Command.List
    if cmd_str == "list" || cmd_str == "ls" {
        command = Command.List
    } else if cmd_str == "inspect" {
        command = Command.Inspect
    } else if cmd_str == "remove" || cmd_str == "rm" {
        command = Command.Remove
    } else {
        term.eprint("error: unknown command '{cmd_str}'")
        panic("unknown command")
    }

    name := ""
    format := "text"
    dry_run := false
    json_flag := false

    i := 2
    loop i < args.len() {
        arg :: args[i]
        if arg == "--json" {
            json_flag = true
            i += 1
        } else if arg == "--format" {
            if i + 1 >= args.len() {
                term.eprint("error: --format requires a value")
                panic("missing value")
            }
            format = ~args[i + 1]
            i += 2
        } else if arg == "--dry-run" {
            dry_run = true
            i += 1
        } else if arg.starts_with("--") {
            term.eprint("error: unknown option '{arg}'")
            panic("unknown option")
        } else {
            name = ~arg
            i += 1
        }
    }

    if json_flag -> format = "json"

    cmd_name :: if command == {
        .List -> "list"
        .Inspect -> "inspect"
        .Remove -> "remove"
    }

    print("{cmd_name} name={name} format={format} dry_run={dry_run}")
