                    values[i] = ~value
                    found = true
                    break
                }
            }
            if !found {
                keys.push(~key)
                values.push(~value)
            }
        } else if kind == "delete" {
            if parts.len() < 2 {
                term.eprint("error: malformed delete record: {line}")
                panic("malformed")
            }
            key :: parts[1]
            new_keys := [String]{}
            new_values := [String]{}
            loop i in 0..<keys.len() {
                if keys[i] != key {
                    new_keys.push(~keys[i])
                    new_values.push(~values[i])
                }
            }
            keys = new_keys
            values = new_values
        } else {
            term.eprint("error: unknown record kind '{kind}' in line: {line}")
            panic("unknown record kind")
        }
    }

    loop i in 0..<keys.len() {
        print("{keys[i]}={values[i]}")
    }
