use core.process as process

fn escape_json(s: String) String -> {
    result := ""
    loop ch in s.chars() {
        if ch == '"' -> result += "\\\""
        else if ch == '\\' -> result += "\\\\"
        else if ch == '\n' -> result += "\\n"
        else if ch == '\t' -> result += "\\t"
        else -> result += "{ch}"
    }
    return result
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    text :: files.read(path) ?? panic("read failed")

    name := ""
    count := 0
    note := ""

    loop line in text.trim().lines() {
        parts :: line.split("\t").to_list()
        if parts.len() < 2 -> next
        key :: parts[0].trim()
        value :: parts[1].trim()
        if key == "name" -> name = value
        else if key == "count" -> count = Int.parse(value) ?? 0
        else if key == "note" -> note = value
    }

    escaped_name :: escape_json(name)
    escaped_note :: escape_json(note)
    print("{{\"count\":{count},\"name\":\"{escaped_name}\",\"note\":\"{escaped_note}\"}}")
}","correction_passes":2,"commands":["jet check T4.jet","jet run T4.jet -- report.tsv"],"observed":["check passed with warnings only","stdout: {"count":2,"name":"Ada","note":"line \"one\""}"],"notes":"Parses TSV key-value pairs, builds report fields, escapes JSON control characters manually, outputs canonical JSON with count/name/note key order."}}
